%[text] %[text:anchor:T_D48C173C] # High Voltage Battery - Simulation Case
%[text] %[text:anchor:H_1B376934] ## Random current
mdl = "BatteryHV_TestModel";
load_system(mdl)

% Load model parameters.
BatteryHV_TestModelSetup

% Select battery model.
BatteryHV_setRefsub_Primitive %[output:291404f5]
% Setup simulation case.
BatteryHV_setSimCase_Random( ... %[output:group:2403226e] %[output:296f7f2b]
  RandomSeed = 125, ... %[output:296f7f2b]
  NumTransitions = 20, ... %[output:296f7f2b]
  InitialSOC_pct = 50 ); %[output:group:2403226e] %[output:296f7f2b]
% Run simulation.
simOut = sim(mdl);

% Collect logged signals and visualize.
% The basic version of the battery block does not simulate battery temperature.
logged_signals = extractTimetable(simOut.logsout);
BatteryHV_ResultsPlot(Timetable=logged_signals); %[output:4be2d8bd]
